import json
from math import isqrt

solutions = []
N = 600  # exhaustive search bound for n
for n in range(N + 1):
    b = 2 ** (n + 1) - 1
    c = 2 * 3 ** n
    D = b * b - 4 * c
    if D < 0:
        continue
    s = isqrt(D)
    if s * s != D:
        continue
    for num in {b + s, b - s}:
        if num % 2 == 0:
            m = num // 2
            if m >= 0 and m * m + c == m * b:
                solutions.append((m, n))

solutions = sorted(set(solutions))
print(json.dumps({
    "final_answer": ", ".join(f"({m},{n})" for m, n in solutions),
    "evidence": {
        "method": "quadratic in m per n, exact integer discriminant test",
        "n_range": [0, N],
        "solutions": solutions,
    }
}))
