    i = 2
    while i*i <= n:
        if n % i == 0: return False
        i += 1
    return True

def amp(a, b): return a-b if a*b > 0 else a+b
def at(a, b): return amp(a, b) if a*b > 0 else a+b
def bang(a, b): return min(a, b) if (isprime(a) or isprime(b)) else max(a, b)
def hsh(a, b):
    g = math.gcd(a, b)
    return at(a, b) if g == 1 else g

def ap(op, a, b):
    if op == "+": return a+b
    if op == "-": return a-b
    if op == "*": return a*b
    if op == "&": return amp(a, b)
    if op == "!": return bang(a, b)
    if op == "@": return at(a, b)
    if op == "#": return hsh(a, b)
    raise ValueError(op)

