from math import gcd

def isprime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def op_and(a, b):
    return a - b if a * b > 0 else a + b

def op_bang(a, b):
    return min(a, b) if (isprime(a) or isprime(b)) else max(a, b)

def op_at(a, b):
    return op_and(a, b) if a * b > 0 else a + b

def op_hash(a, b):
    g = gcd(a, b)
    return op_at(a, b) if g == 1 else g

OPS = {
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '&': op_and,
    '!': op_bang,
    '@': op_at,
    '#': op_hash,
}

W = {'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
     'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10}

def val(t):
    return W[t] if t in W else int(t)

def run(start, steps):
    x = start
    for s in steps.split(';'):
        s = s.strip()
        o, b = s.split()
        b = val(b)
        for ch in o:
            x = OPS[ch](x, b)
    return x

