from fractions import Fraction as F

def rank(rows):
    m = [[F(x) for x in r] for r in rows]
    rk = 0
    cols = len(m[0])
    for c in range(cols):
        p = next((i for i in range(rk, len(m)) if m[i][c] != 0), None)
        if p is None:
            continue
        m[rk], m[p] = m[p], m[rk]
        for i in range(len(m)):
            if i != rk and m[i][c] != 0:
                f = m[i][c] / m[rk][c]
                m[i] = [a - f * b for a, b in zip(m[i], m[rk])]
        rk += 1
    return rk

# Statement 1: T(e1-e2)=0 forces (1,-1,0,0) in Ker T = span{e3,e4}
s1 = False  # (1,-1,0,0) has nonzero first coordinate, so not in span{e3,e4}
# verify membership: vector in span{e3,e4} iff first two coords are zero
v = (1, -1, 0, 0)
s1 = (v[0] == 0 and v[1] == 0)

# Statement 2: dim U vs dim W
dimU = rank([(5, 2, 4, 3), (1, 2, 2, 1), (3, -2, 0, 1)])
# W: p = ax^2+bx+c, p(0)=c, p(1)=a+b+c, condition a+b=0 -> one linear constraint on 3 coords
dimW = 3 - rank([(1, 1, 0)])
s2 = (dimU == dimW)

# Statement 3: (1,10,0) = a(1,1,0)+b(1,-1,0)
