from itertools import combinations

# Part 1: player counts. Four distinct positive integers summing to 12,
# where one equals the product of two others.
nums = []
for c in combinations(range(1, 12), 4):
    if sum(c) != 12:
        continue
    ok = any(
        c[k] == c[i] * c[j]
        for k in range(4)
        for i in range(4)
        for j in range(i + 1, 4)
        if k != i and k != j
    )
    if ok:
        nums.append(c)
print("count sets:", nums)

# Part 2: valid event choices.
E = ["L", "S", "H", "J", "P"]  # long-distance run, sprint, high jump, long jump, shot put


def valid(s, jump_both):
    if "L" in s:
        if "S" in s:
            return False
        if "J" in s:
            return False
        if jump_both and "H" in s:
            return False
    if "J" in s and ("L" in s or "P" in s):
        return False
    return True


options = {
    "A": ["S", "P"],
    "B": ["S", "J"],
    "C": ["P", "H"],
    "D": ["L", "H"],
}

for jump_both in (True, False):
    choices = []
    for r in (1, 2):
        for s in combinations(E, r):
            if "L" in s and valid(set(s), jump_both):
                choices.append(set(s))
    print("jump_both =", jump_both, "valid choices with L:", choices)
    impossible = []
    for name, evs in options.items():
        # "X or Y": possible if the grade's choice can include X or Y
        # (for D, "long run" is the grade's already-chosen event, so choosing only L works)
        possible = any(any(e in s for e in evs) for s in choices)
        print(name, evs, "possible" if possible else "IMPOSSIBLE")
        if not possible:
            impossible.append(name)
    print("impossible options:", impossible)
    if impossible == ["B"]:
        print("correct answer is B; submitted D is wrong")

submitted = "D"
print("CHECK PASS" if submitted == "B" else "CHECK FAIL")
