def tile(n, limit):
    grid = [[0]*n for _ in range(n)]
    t0 = time.time()
    class TO(Exception): pass
    def solve(pos):
        if time.time() - t0 > limit:
            raise TO
        while pos < n*n and grid[pos//n][pos % n]:
            pos += 1
        if pos == n*n:
            return True
        r, c = divmod(pos, n)
        for s in SHAPES:
            cells = [(r+dr, c+dc) for dr, dc in s]
            if all(0 <= a < n and 0 <= b < n and not grid[a][b] for a, b in cells):
                for a, b in cells:
                    grid[a][b] = 1
                if solve(pos+1):
                    return True
                for a, b in cells:
                    grid[a][b] = 0
        return False
    try:
        return solve(0)
    except TO:
        return None

